//! Experimental upload transport. Completion is unavailable until durable storage is integrated.
use std::{path::Path,sync::{Arc,OnceLock,Mutex,mpsc},time::{Duration,Instant}};
use serde_json::{json,Value};
use crate::{agent_profiles,agent_socket,agent_upload_lifecycle::{Owner,Uploads,CompletionError},workspace_worker::Workers};
struct LocalSpool {spool:crate::agent_encrypted_spool::EncryptedSpool,title:String,request:String,digest:String}
type LocalMap=Arc<Mutex<std::collections::HashMap<String,Arc<Mutex<LocalSpool>>>>>;
struct State { uploads:Arc<Uploads>, cleanup:mpsc::SyncSender<Owner>, locals:LocalMap }
static STATE:OnceLock<State>=OnceLock::new();
pub fn active_upload_count()->Result<usize,&'static str>{match STATE.get(){Some(s)=>s.uploads.active_count(Instant::now()),None=>Ok(0)}}
type CancelKey=(String,String,String,String);
fn cancelled_requests()->&'static Mutex<std::collections::HashMap<CancelKey,Instant>>{static KEYS:OnceLock<Mutex<std::collections::HashMap<CancelKey,Instant>>>=OnceLock::new();KEYS.get_or_init(||Mutex::new(std::collections::HashMap::new()))}
fn cancelled_key(agent:&str,wid:&str,session:&str,id:&str)->CancelKey{(agent.into(),wid.into(),session.into(),id.into())}
fn mark_cancelled(key:CancelKey)->Result<(),()>{let mut keys=cancelled_requests().lock().map_err(|_|())?;let now=Instant::now();keys.retain(|_,t|now.saturating_duration_since(*t)<Duration::from_secs(60));if !keys.contains_key(&key)&&keys.len()>=1024{return Err(())}keys.insert(key,now);Ok(())}
fn is_cancelled(key:&CancelKey)->bool{match cancelled_requests().lock(){Ok(mut keys)=>{let now=Instant::now();keys.retain(|_,t|now.saturating_duration_since(*t)<Duration::from_secs(60));keys.contains_key(key)},Err(_)=>true}}

fn state(workers:&Arc<Workers>)->&'static State {STATE.get_or_init(||{
 #[cfg(feature="test-hook")] let idle=std::env::var("ATLAS_TEST_UPLOAD_IDLE_MS").ok().and_then(|v|v.parse::<u64>().ok()).filter(|v|*v>=50&&*v<=60000).map(Duration::from_millis).unwrap_or(Duration::from_secs(60));
 #[cfg(not(feature="test-hook"))] let idle=Duration::from_secs(60);
 let uploads=Arc::new(Uploads::new(16,idle));let locals:LocalMap=Arc::new(Mutex::new(std::collections::HashMap::new()));let (cleanup,rx)=mpsc::sync_channel::<Owner>(16);let rx=Arc::new(Mutex::new(rx));
 for _ in 0..4 {let rx=rx.clone();let w=workers.clone();let u=uploads.clone();let locals=locals.clone();std::thread::spawn(move||loop{let owner=match rx.lock(){Ok(r)=>match r.recv(){Ok(o)=>o,Err(_)=>return},Err(_)=>return};#[cfg(feature="test-hook")] if let Some(path)=std::env::var_os("ATLAS_TEST_AGENT_UPLOAD_CLEANUP_BARRIER"){let dir=std::path::Path::new(&path);if dir.join("enabled").exists(){let _=std::fs::write(dir.join("ready"),b"ready");let deadline=Instant::now()+Duration::from_secs(15);while !dir.join("resume").exists()&&Instant::now()<deadline{std::thread::sleep(Duration::from_millis(10));}}}if owner.session.starts_with("p:")||owner.session.starts_with("l:"){if let Ok(mut all)=locals.lock(){all.remove(&owner.worker_stream);}u.cleanup_complete(&owner);continue}loop{let result=w.request_session(&owner.workspace,&owner.session,&json!({"action":"upload-cancel","stream":owner.worker_stream}));if result.is_ok_and(|v|v.get("ok").is_some()||v["error"].as_str()==Some("invalid stream"))||w.session(&owner.workspace).ok().as_deref()!=Some(owner.session.as_str()){u.cleanup_complete(&owner);break}std::thread::sleep(Duration::from_millis(250));}});}
 let u=uploads.clone();let tx=cleanup.clone();std::thread::spawn(move||loop{std::thread::sleep(Duration::from_secs(1));for o in u.cancel_matching(None,None,Instant::now()){if let Err(mpsc::TrySendError::Full(o)|mpsc::TrySendError::Disconnected(o))=tx.try_send(o){u.retry_cleanup(&o);}}});
 State{uploads,cleanup,locals}
})}
fn worker(w:&Workers,id:&str,session:&str,input:Value)->Result<Value,()>{w.request_session(id,session,&input).map_err(|_|())?.get("ok").cloned().ok_or(())}
pub(crate) fn current_session(root:&Path,default:&Path,workers:&Workers,protected:&crate::protected::Protected,wid:&str)->Option<String>{
 use std::os::unix::fs::MetadataExt;
 if let Ok(session)=workers.session(wid){return Some(session)}if let Some(cookie)=protected.session(wid){return Some(format!("p:{cookie}"))}
 if crate::external_registry::entries(root).ok()?.iter().any(|v|v["id"]==wid)||(wid=="default"&&root.join(".default-deleted").exists()){return None}
 let path=crate::workspace_paths::resolve(root,default,wid);if !crate::valid_workspace(&path){return None}let m=std::fs::symlink_metadata(path).ok()?;Some(format!("l:{}:{}",m.dev(),m.ino()))
}
fn queue(s:&State,o:Owner){if let Err(mpsc::TrySendError::Full(o)|mpsc::TrySendError::Disconnected(o))=s.cleanup.try_send(o){s.uploads.retry_cleanup(&o);}}
pub fn cancel_actor(id:&str){if let Some(s)=STATE.get(){for o in s.uploads.cancel_matching(Some(id),None,Instant::now()){queue(s,o);}}}
pub fn cancel_workspace(id:&str){if let Some(s)=STATE.get(){for o in s.uploads.cancel_matching(None,Some(id),Instant::now()){queue(s,o);}}}
pub fn handle(mut req:agent_socket::AgentRequest,root:&Path,default:&Path,wid:&str,credential:&str,workers:&Arc<Workers>,protected:&Arc<crate::protected::Protected>,model:&Mutex<crate::ModelState>,states:&Arc<Mutex<std::collections::HashMap<String,String>>>){
 let Some(actor)=agent_profiles::identity(root,credential)else{return agent_socket::answer(req,403,json!({"error":"Forbidden"}))};
 if !agent_profiles::authorized(root,credential,wid,"add"){return agent_socket::answer(req,403,json!({"error":"Forbidden"}))}
 let input=match agent_socket::body(&mut req){Ok(v)=>v,Err(_)=>return agent_socket::answer(req,400,json!({"error":"Invalid request"}))};
 let session=match current_session(root,default,workers,protected,wid){Some(v)=>v,None=>return agent_socket::answer(req,501,json!({"error":"Workspace unavailable"}))};let s=state(workers);let now=Instant::now();
 match input["action"].as_str(){
  Some("begin")=>{let Some(name)=input["name"].as_str().filter(|v|!v.is_empty()&&*v!="."&&*v!=".."&&!v.contains(['/', '\\','\0'])&&v.len()<=255)else{return agent_socket::answer(req,400,json!({"error":"Invalid filename"}))};let Some(size)=input["size"].as_u64().filter(|v|*v<=10*1024*1024*1024)else{return agent_socket::answer(req,400,json!({"error":"Invalid size"}))};let transactional=input["request_id"].as_str().is_some()||input["digest"].as_str().is_some();let (request_id,digest)=if transactional{let Some(r)=input["request_id"].as_str().filter(|v|!v.is_empty()&&v.len()<=128)else{return agent_socket::answer(req,400,json!({"error":"Invalid request id"}))};let Some(d)=input["digest"].as_str().filter(|v|v.len()==64&&v.bytes().all(|c|c.is_ascii_hexdigit()&&!c.is_ascii_uppercase()))else{return agent_socket::answer(req,400,json!({"error":"Invalid digest"}))};(r,d)}else{("","")};let signature=if transactional{use sha2::{Digest,Sha256};format!("{:x}",Sha256::digest(serde_json::to_vec(&(name,size,digest)).unwrap_or_default()))}else{String::new()};let owner=Owner{agent:actor.clone(),workspace:wid.to_owned(),session:session.clone(),worker_stream:String::new(),transactional,request_id:request_id.to_owned(),signature:signature.clone()};let id=uuid::Uuid::new_v4().simple().to_string();let gate=agent_profiles::publication_gate().lock();let allowed=gate.is_ok()&&agent_profiles::authorized(root,credential,wid,"add")&&current_session(root,default,workers,protected,wid).as_deref()==Some(session.as_str());if !allowed {drop(gate);return agent_socket::answer(req,403,json!({"error":"Forbidden"}))}if transactional {if is_cancelled(&cancelled_key(&actor,wid,&session,request_id)){drop(gate);return agent_socket::answer(req,409,json!({"error":"Request cancelled"}))}match s.uploads.find_request(&actor,wid,&session,request_id,&signature){Ok(Some((existing,ready,offset)))=>{drop(gate);return agent_socket::answer(req,if ready{200}else{202},json!({"upload":existing,"pending":!ready,"offset":offset}))},Err(_)=>{drop(gate);return agent_socket::answer(req,409,json!({"error":"Request conflict"}))},Ok(None)=>{}}}let accepted=s.uploads.begin(id.clone(),owner,size,now);drop(gate);match accepted{Ok(())=>{},Err("quota exceeded")=>return agent_socket::answer(req,429,json!({"error":"Общий лимит исходных данных загрузок — 10 ГиБ (плюс место для шифрования)","code":"upload_quota"})),Err(_)=>return agent_socket::answer(req,409,json!({"error":"Upload busy"}))}
   #[cfg(feature="test-hook")] if let Some(dir)=std::env::var_os("ATLAS_TEST_AGENT_UPLOAD_BEGIN_BARRIER"){let dir=std::path::Path::new(&dir);let _=std::fs::write(dir.join("ready"),b"ready");let deadline=Instant::now()+Duration::from_secs(15);while !dir.join("resume").exists()&&Instant::now()<deadline{std::thread::sleep(Duration::from_millis(10));}}
   let stream=if session.starts_with("p:")||session.starts_with("l:"){if !transactional{s.uploads.abandon_pending(&id);return agent_socket::answer(req,501,json!({"error":"Transactional metadata required"}))}let spool=match crate::agent_encrypted_spool::EncryptedSpool::new(size){Ok(v)=>v,Err(_)=>{s.uploads.abandon_pending(&id);return agent_socket::answer(req,503,json!({"error":"Upload unavailable"}))}};let stream=uuid::Uuid::new_v4().simple().to_string();let entry=LocalSpool{spool,title:name.to_owned(),request:request_id.to_owned(),digest:digest.to_owned()};match s.locals.lock(){Ok(mut map)=>{map.insert(stream.clone(),Arc::new(Mutex::new(entry)));},Err(_)=>{s.uploads.abandon_pending(&id);return agent_socket::answer(req,503,json!({"error":"Upload unavailable"}))}}stream}else{let Some(stream)=worker(workers,wid,&session,if transactional {json!({"action":"agent-upload-begin","name":name,"size":size,"actor":format!("agent:{actor}"),"request_id":request_id,"digest":digest})} else {json!({"action":"upload-begin","name":name,"size":size})}).ok().and_then(|v|v["stream"].as_str().map(str::to_owned))else{s.uploads.abandon_pending(&id);return agent_socket::answer(req,409,json!({"error":"Upload unavailable"}))};stream};match s.uploads.set_stream(&id,stream){Ok(Some(o))=>{queue(s,o);agent_socket::answer(req,403,json!({"error":"Upload cancelled"}))},Ok(None)=>agent_socket::answer(req,201,json!({"upload":id})),Err(_)=>agent_socket::answer(req,503,json!({"error":"Upload unavailable"}))}},
  Some("chunk")=>{let Some(id)=input["upload"].as_str()else{return agent_socket::answer(req,400,json!({"error":"Invalid upload"}))};let Some(offset)=input["offset"].as_u64()else{return agent_socket::answer(req,400,json!({"error":"Invalid offset"}))};let Some(bytes)=input["bytes"].as_array().filter(|b|!b.is_empty()&&b.len()<=16000&&b.iter().all(|v|v.as_u64().is_some_and(|n|n<=255)))else{return agent_socket::answer(req,400,json!({"error":"Invalid bytes"}))};let ticket=match s.uploads.reserve(id,&actor,wid,&session,offset,bytes.len() as u64,now){Ok(v)=>v,Err(_)=>return agent_socket::answer(req,409,json!({"error":"Upload unavailable"}))};let result=if session.starts_with("p:")||session.starts_with("l:"){let entry=s.locals.lock().ok().and_then(|m|m.get(&ticket.owner.worker_stream).cloned());match entry{Some(entry)=>match entry.lock(){Ok(mut entry)=>{let data=bytes.iter().filter_map(|v|v.as_u64().map(|v|v as u8)).collect::<Vec<_>>();entry.spool.push(&data).map(|_|json!({})).map_err(|_|())},Err(_)=>Err(())},None=>Err(())}}else{worker(workers,wid,&session,json!({"action":"upload-chunk","stream":ticket.owner.worker_stream,"bytes":bytes}))};let allowed=agent_profiles::authorized(root,credential,wid,"add")&&current_session(root,default,workers,protected,wid).as_deref()==Some(session.as_str());match s.uploads.complete(id,&ticket,bytes.len() as u64,result.is_ok()&&allowed,Instant::now()){Ok(offset)=>agent_socket::answer(req,200,json!({"offset":offset})),Err(CompletionError::CancelWorker(o))=>{queue(s,o);agent_socket::answer(req,409,json!({"error":"Upload cancelled"}))},Err(_)=>agent_socket::answer(req,409,json!({"error":"Upload cancelled"}))}},
  Some("finish")=>{let Some(id)=input["upload"].as_str()else{return agent_socket::answer(req,400,json!({"error":"Invalid upload"}))};let ticket=match s.uploads.reserve_finish(id,&actor,wid,&session,now){Ok(v)=>v,Err(_)=>return agent_socket::answer(req,409,json!({"error":"Upload unavailable or incomplete"}))};if !ticket.owner.transactional{if let Some(o)=s.uploads.cancel_one(id,&actor,wid,&session){queue(s,o)}let _=s.uploads.complete(id,&ticket,0,false,Instant::now());return agent_socket::answer(req,501,json!({"error":"Upload completion not implemented"}))}#[cfg(feature="test-hook")] if let Some(dir)=std::env::var_os("ATLAS_TEST_AGENT_UPLOAD_FINISH_BARRIER"){let dir=std::path::Path::new(&dir);if dir.join("enabled").exists(){let _=std::fs::write(dir.join("ready"),b"ready");let deadline=Instant::now()+Duration::from_secs(15);while !dir.join("resume").exists()&&Instant::now()<deadline{std::thread::sleep(Duration::from_millis(10));}}}let actor_id=format!("agent:{actor}");let lease=match crate::note_locks().acquire_checked_with_auth(wid,&format!("#agent-upload:{id}"),&actor_id,false,Duration::from_secs(120),||Ok(false),||{let gate=agent_profiles::publication_gate().lock().map_err(|_|crate::note_edit_lock::Error::Poisoned)?;if agent_profiles::authorized(root,credential,wid,"add"){Ok(gate)}else{Err(crate::note_edit_lock::Error::Expired)}}){Ok(v)=>v,Err(_)=>{if let Some(o)=s.uploads.cancel_one(id,&actor,wid,&session){queue(s,o)}let _=s.uploads.complete(id,&ticket,0,false,Instant::now());return agent_socket::answer(req,403,json!({"error":"Forbidden or busy"}))}};let result=crate::note_locks().with_lease(&lease,||{#[cfg(feature="test-hook")] if let Some(dir)=std::env::var_os("ATLAS_TEST_AGENT_UPLOAD_COMMIT_BARRIER"){let dir=std::path::Path::new(&dir);if dir.join("enabled").exists(){let _=std::fs::write(dir.join("ready"),b"ready");let deadline=Instant::now()+Duration::from_secs(15);while !dir.join("resume").exists()&&Instant::now()<deadline{std::thread::sleep(Duration::from_millis(10));}}}if ticket.cancelled()||!agent_profiles::authorized(root,credential,wid,"add"){return Err(())}if let Some(cookie)=session.strip_prefix("p:").and_then(|v|v.parse::<u64>().ok()){let entry=s.locals.lock().ok().and_then(|m|m.get(&ticket.owner.worker_stream).cloned()).ok_or(())?;let entry=entry.lock().map_err(|_|())?;let reader=entry.spool.reader().map_err(|_|())?;protected.agent_upload_file(wid,cookie,&actor_id,&entry.request,&entry.title,&entry.digest,reader,||!ticket.cancelled()&&agent_profiles::authorized(root,credential,wid,"add")).map_err(|_|())}else if session.starts_with("l:"){let entry=s.locals.lock().ok().and_then(|m|m.get(&ticket.owner.worker_stream).cloned()).ok_or(())?;let entry=entry.lock().map_err(|_|())?;let mut reader=entry.spool.reader().map_err(|_|())?;let path=crate::workspace_paths::resolve(root,default,wid);let _guard=atlas_native_storage_contract::workspace_lock(&path).map_err(|_|())?;if current_session(root,default,workers,protected,wid).as_deref()!=Some(session.as_str()){return Err(())}atlas_native_storage_contract::agent_file_upload::create_locked(&path,&actor_id,&entry.request,&entry.title,&entry.digest,&mut reader,||{if ticket.cancelled()||!agent_profiles::authorized(root,credential,wid,"add"){return Err("Upload cancelled".into())}crate::mark_agent_dirty(&path)?;Ok(())}).map_err(|_|())}else{worker(workers,wid,&session,json!({"action":"agent-upload-finish","stream":ticket.owner.worker_stream}))}});let _=crate::note_locks().release(&lease);match result{Ok(Ok(v))=>{let _=s.uploads.finish(id,&ticket);if session.starts_with("p:")||session.starts_with("l:"){if let Ok(mut map)=s.locals.lock(){map.remove(&ticket.owner.worker_stream);}}let service=model.lock().ok().and_then(|m|if let crate::ModelState::Ready(s)=&*m{Some(s.clone())}else{None});if current_session(root,default,workers,protected,wid).as_deref()==Some(session.as_str()){if session.starts_with("p:"){if let Some(service)=service{protected.agent_schedule(wid,service)}}else if session.starts_with("l:"){if let Some(service)=service{let path=crate::workspace_paths::resolve(root,default,wid);let _=service.enqueue(&path,v["id"].as_str());}}else{crate::external_routes::enqueue(workers.clone(),states.clone(),wid.to_owned(),service);}}crate::signal_agent_board(wid);agent_socket::answer(req,201,v)},_=>{if let Some(o)=s.uploads.cancel_one(id,&actor,wid,&session){queue(s,o)}let _=s.uploads.complete(id,&ticket,0,false,Instant::now());agent_socket::answer(req,409,json!({"error":"Upload failed"}))}}},
  Some("cancel")=>{let gate=match agent_profiles::publication_gate().lock(){Ok(v)=>v,Err(_)=>return agent_socket::answer(req,503,json!({"error":"Unavailable"}))};if !agent_profiles::authorized(root,credential,wid,"add"){drop(gate);return agent_socket::answer(req,403,json!({"error":"Forbidden"}))}let owner=if let Some(id)=input["upload"].as_str(){s.uploads.cancel_one(id,&actor,wid,&session)}else if let Some(id)=input["request_id"].as_str().filter(|v|!v.is_empty()&&v.len()<=128){if mark_cancelled(cancelled_key(&actor,wid,&session,id)).is_err(){drop(gate);return agent_socket::answer(req,503,json!({"error":"Cancellation unavailable"}))}s.uploads.cancel_request(&actor,wid,&session,id)}else{drop(gate);return agent_socket::answer(req,400,json!({"error":"Invalid upload"}))};let marked=owner.as_ref().is_none_or(|o|!o.transactional||mark_cancelled(cancelled_key(&actor,wid,&session,&o.request_id)).is_ok());drop(gate);if let Some(owner)=owner{queue(s,owner)}if !marked{return agent_socket::answer(req,503,json!({"error":"Cancellation unavailable"}))}agent_socket::answer(req,202,json!({"ok":true,"pending":true}))},
  _=>agent_socket::answer(req,501,json!({"error":"Upload completion not implemented"}))
 }
}
#[cfg(test)] mod cleanup_queue_tests {
 use super::*;
 #[test] fn full_cleanup_queue_retries_without_losing_worker(){
  let uploads=Uploads::new(2,Duration::from_secs(60));let now=Instant::now();
  for (id,agent) in [("x","a"),("y","b")] {uploads.begin(id.into(),Owner{agent:agent.into(),workspace:"w".into(),session:"s".into(),worker_stream:id.into(),transactional:true,request_id:id.into(),signature:id.into()},0,now).unwrap();}
  let (tx,rx)=mpsc::sync_channel(1);let handles=uploads.cancel_matching(None,Some("w"),now);assert_eq!(handles.len(),2);
  for owner in handles {if let Err(mpsc::TrySendError::Full(owner)|mpsc::TrySendError::Disconnected(owner))=tx.try_send(owner){uploads.retry_cleanup(&owner);}}
  let first=rx.recv().unwrap();uploads.cleanup_complete(&first);let retry=uploads.cancel_matching(None,None,now);assert_eq!(retry.len(),1);assert_ne!(retry[0].worker_stream,first.worker_stream);uploads.cleanup_complete(&retry[0]);
 }
}
